def email():
    domains = ["gmail.com", "yandex.ru", "mail.ru", "outlook.com"]
    name = ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
    domain = random.choice(domains)
    return f"{name}@{domain}"


